<script setup lang="ts">
import { onMounted, ref } from 'vue'; import type { DeviceSummary } from '@cyberboard/types'; import StatusBadge from '@cyberboard/ui/components/StatusBadge.vue'; import StatePanel from '@cyberboard/ui/components/StatePanel.vue'; import { getApiErrorMessage, normalizeList, portalApi } from '../api'
const loading=ref(true); const error=ref(''); const devices=ref<DeviceSummary[]>([])
async function load(){loading.value=true;error.value='';try{devices.value=normalizeList(await portalApi.listDevices({page:1,pageSize:50}))}catch(cause){devices.value=[];error.value=getApiErrorMessage(cause)}finally{loading.value=false}};onMounted(load)
</script>
<template><div class="portal-heading"><div><p class="eyebrow">访问安全</p><h1>设备</h1><p>查看使用过订阅的设备和最近活动。</p></div><button class="button button--secondary" type="button" :disabled="loading" @click="load">{{loading?'加载中…':'刷新'}}</button></div><section class="portal-panel"><StatePanel v-if="loading" title="正在加载设备" description="正在读取设备活动。"/><StatePanel v-else-if="error" title="设备加载失败" :description="error" action-label="重试" @action="load"/><StatePanel v-else-if="!devices.length" title="暂无设备" description="服务端尚未返回设备记录。"/><div v-else class="device-list"><div v-for="device in devices" :key="device.id" class="device-row"><div><strong>{{device.name}}</strong><small>{{device.platform}} · {{device.ipAddress??'地址未提供'}}</small></div><StatusBadge :status="device.status"/><span class="muted">{{device.lastSeenAt??'从未活动'}}</span></div></div></section></template>
